import { isPromiseDiscardedError, raceScheduler } from './race-scheduler';
import { safeQueueRace } from './safe-queue-race';
import { safeRace, useSafeRace } from './safe-race';
import { renderHook } from '@testing-library/react-hooks';

const fakeFetcher = <T>(expectValue?: T, wait?: number, failed?: boolean) =>
  new Promise<T | undefined>((resolve, reject) => {
    setTimeout(() => {
      if (failed) {
        reject(new Error('error'));
      } else {
        resolve(expectValue);
      }
    }, wait);
  });

const wait = (time: number) =>
  new Promise<void>(resolve => {
    setTimeout(() => {
      resolve();
    }, time);
  });

function generateRandomNumber() {
  return Math.floor(Math.random() * (1000 - 100 + 1)) + 200;
}

describe('safeRace 测试', () => {
  test('仅调用一次亦正常响应', async () => {
    const safeFetcher = safeRace(fakeFetcher);
    const data = await safeFetcher(1, 100);
    expect(data).toBe(1);
  });

  test('常规多次调用后正常响应', async () => {
    const safeFetcher = safeRace(fakeFetcher);

    const callback = jest.fn();

    await Promise.race(Array.from({ length: 10 }).map((_, i) => safeFetcher(i, generateRandomNumber()).then(callback)));

    // 调用10次，只会响应 1 次，并且响应数据是最后一次调用应该返回的数据
    expect(callback).toBeCalledTimes(1);
    expect(callback).toBeCalledWith(9);

    await Promise.race(Array.from({ length: 5 }).map((_, i) => safeFetcher(i, generateRandomNumber()).then(callback)));

    // 再来5次调用
    expect(callback).toBeCalledTimes(2);
    expect(callback).toBeCalledWith(4);
  });

  test('在多次调用后，响应前再次调用，应为后者产生的数据', async () => {
    const firstCallGroupCallback = jest.fn();
    const safeFetcher = safeRace(fakeFetcher);

    const promises = Array.from({ length: 3 }).map((_, i) => {
      const wait = generateRandomNumber();
      return [safeFetcher(i, wait).then(firstCallGroupCallback), wait] as const;
    });

    const lastWait = promises.map(([, wait]) => wait).at(-1)!;

    await wait(lastWait - 100);

    const promiseInstances = promises.map(([p]) => p);
    promiseInstances.push(safeFetcher('last', 100));

    const data = await Promise.race(promiseInstances);

    expect(data).toBe('last');
  });

  test('仅最后一次调用发生异常能感知', async () => {
    const callback = jest.fn();
    const onError = jest.fn();
    const safeFetcher = safeRace(fakeFetcher);

    await Promise.race(
      Array.from({ length: 3 }).map((_, i) =>
        safeFetcher(i, generateRandomNumber(), i === 1)
          .then(callback)
          .catch(onError),
      ),
    );

    expect(callback).toBeCalledWith(2);
    expect(onError).not.toBeCalled();

    await Promise.race(
      Array.from({ length: 2 }).map((_, i) =>
        safeFetcher(i, generateRandomNumber(), i === 1)
          .then(callback)
          .catch(onError),
      ),
    );

    expect(callback).toBeCalledTimes(1);
    expect(onError).toBeCalled();
  });

  test('支持传入 null 和 undefined', () => {
    const safeFetcher = safeRace(null);
    const safeFetcher2 = safeRace(undefined);
    expect(safeFetcher).toBe(null);
    expect(safeFetcher2).toBe(undefined);

    const nullHook = renderHook(() => useSafeRace(null));

    expect(nullHook.result.current).toBe(null);

    const hook = renderHook(() => useSafeRace(fakeFetcher, { enabled: false }));

    expect(hook.result.current === fakeFetcher).toBe(true);
  });

  test('支持禁用', () => {
    const safeFetcher = safeRace(fakeFetcher, { enabled: false });
    const safeFetcher2 = safeRace(fakeFetcher);

    expect(safeFetcher === fakeFetcher).toBe(true);
    expect(safeFetcher2 === fakeFetcher).toBe(false);
  });

  test('测试多次调用可能不返回 Promise 的情况，前面的promise不影响立即返回的结果', async () => {
    const safeFetcher = safeRace((num: number) => {
      if (num > 0) {
        return fakeFetcher(num, 1e3);
      }

      return num;
    });

    void safeFetcher(1);
    const z = safeFetcher(0);

    await wait(1e3);
    expect(z).toBe(0);
  });

  test('返回 null 之后等值', async () => {
    const safeFetcher = safeRace(<T>(num: T) => num);

    safeFetcher(null);
    safeFetcher(undefined);
    void safeFetcher(fakeFetcher(0, 200));
    const a = safeFetcher(fakeFetcher(1, 100));
    await wait(300);

    expect(await a).toBe(1);
  });
});

describe('raceScheduler 测试', () => {
  test('高低任务优先级常规测试', async () => {
    // eslint-disable-next-line @typescript-eslint/no-unsafe-return -- 安全
    const callback = jest.fn(v => v);

    const { runWithPolling, runWithSearch } = raceScheduler({
      // 模拟轮询场景
      runWithPolling: { asyncFn: fakeFetcher, priority: 1 },
      // 模拟用户搜索场景
      runWithSearch: { asyncFn: fakeFetcher, priority: 100 },
    });

    const pollingPromises = Array.from({ length: 2 }).map((_, i) => runWithPolling('polling', 500).then(callback));
    await wait(100);
    // 优先级更高
    const searchPromises = Array.from({ length: 2 }).map((_, i) => runWithSearch('search' + i, 100).then(callback));

    const data = await Promise.race([...pollingPromises, ...searchPromises]);

    expect(data).toBe('search1');
    expect(callback).toBeCalledTimes(1);
  });

  test('异常被抛出', async () => {
    const { runWithPolling, runWithSearch } = raceScheduler({
      // 模拟轮询场景
      runWithPolling: { asyncFn: fakeFetcher, priority: 1 },
      // 模拟用户搜索场景
      runWithSearch: { asyncFn: fakeFetcher, priority: 100 },
    });
    const onError = jest.fn();

    const pollingPromises = Array.from({ length: 2 }).map((_, i) => runWithPolling('polling', 500));

    // 优先级更高
    const searchPromises = Array.from({ length: 2 }).map((_, i) =>
      runWithSearch('search' + i, 100, i === 1).catch(onError),
    );

    const data = await Promise.race([...pollingPromises, ...searchPromises]);
    expect(data).toBeUndefined();
    expect(onError).toBeCalledTimes(1);
  });

  test('多任务交叉覆盖', async () => {
    const { fetch1, fetch2, fetch3 } = raceScheduler({
      fetch1: { asyncFn: fakeFetcher, priority: 1 },
      fetch2: { asyncFn: fakeFetcher, priority: 2 },
      fetch3: { asyncFn: fakeFetcher, priority: 3 },
    });

    let fetch1Promise = fetch1('1', 300);
    let fetch2Promise = fetch2('2', 200);
    let fetch3Promise = fetch3('3', 100);
    // 预期不生效
    fetch1Promise = fetch1('11', 50);
    fetch2Promise = fetch2('22', 50);
    fetch3Promise = fetch3('33', 50);

    const data = await Promise.race([fetch1Promise, fetch2Promise, fetch3Promise]);
    expect(data).toBe('33');
  });

  test('promise 被丢弃后抛出异常', async () => {
    const { fetch1, fetch2 } = raceScheduler(
      {
        fetch1: { asyncFn: fakeFetcher, priority: 1 },
        fetch2: { asyncFn: fakeFetcher, priority: 2 },
      },
      { discardedPromiseAction: 'throw-error' },
    );

    const onError = jest.fn();

    const p = fetch2('ok');
    await fetch1().catch(onError);

    expect(isPromiseDiscardedError(onError.mock.calls[0][0])).toBe(true);
    await expect(p).resolves.toBe('ok');
  });
});

describe('safeQueueRace 测试', () => {
  test('basic use', async () => {
    const safeQueueFetcher = safeQueueRace(fakeFetcher);
    const values: number[] = [];
    await Promise.all([
      safeQueueFetcher(1, 1000).then(v => values.push(v!)),
      safeQueueFetcher(2, 500).then(v => values.push(v!)),
      safeQueueFetcher(3, 100).then(v => values.push(v!)),
    ]);
    expect(values).toEqual([1, 2, 3]);

    values.length = 0;

    await Promise.all([
      safeQueueFetcher(4, 100).then(v => values.push(v!)),
      safeQueueFetcher(5, 0).then(v => values.push(v!)),
    ]);

    expect(values).toEqual([4, 5]);
  });

  test('error catch', async () => {
    const safeQueueFetcher = safeQueueRace(fakeFetcher);
    const values: number[] = [];
    await Promise.all([
      safeQueueFetcher(1, 1000).then(v => {
        values.push(v!);
      }),
      safeQueueFetcher(2, 500, true)
        .then(v => {
          values.push(v!);
        })
        .catch(() => {
          values.push(-1);
        }),
      safeQueueFetcher(3, 100, false).then(v => {
        values.push(v!);
      }),
    ]);

    expect(values).toEqual([1, -1, 3]);

    values.length = 0;

    await Promise.all([
      safeQueueFetcher(4, 200).then(v => {
        values.push(v!);
      }),
      safeQueueFetcher(5, 0, true)
        .then(v => {
          values.push(v!);
        })
        .catch(() => {
          values.push(-2);
        }),
    ]);

    expect(values).toEqual([4, -2]);
  });

  test('error be throw', async () => {
    const safeQueueFetcher = safeQueueRace(fakeFetcher);
    const handleCatch = jest.fn();

    await safeQueueFetcher(2, 500, true).catch(handleCatch);

    expect(handleCatch).toBeCalledWith(new Error(`error`));
  });

  test('前一个报错不影响后面的响应', async () => {
    const safeQueueFetcher = safeQueueRace(fakeFetcher);

    // 先 reject
    let error = safeQueueFetcher(1, 0, true);
    let success = safeQueueFetcher(1, 100, false);

    await Promise.all([expect(error).rejects.toEqual(new Error('error')), expect(success).resolves.toBe(1)]);

    // 后 reject
    error = safeQueueFetcher(1, 100, true);
    success = safeQueueFetcher(1, 0, false);

    await Promise.all([expect(error).rejects.toEqual(new Error('error')), expect(success).resolves.toBe(1)]);
  });
});
